using System.Windows; using AutoPecasERP.Core.Entities; using AutoPecasERP.Data.Context; using Microsoft.EntityFrameworkCore; namespace AutoPecasERP.Desktop.Views; public partial class FornecedoresWindow:Window{public FornecedoresWindow(){InitializeComponent();Carregar();}async void Carregar(){using var db=new ErpDbContext();GridDados.ItemsSource=await db.Fornecedores.OrderBy(x=>x.Empresa).ToListAsync();}async void Adicionar_Click(object s,RoutedEventArgs e){if(string.IsNullOrWhiteSpace(Empresa.Text)){MessageBox.Show("Informe a empresa.");return;}using var db=new ErpDbContext();db.Fornecedores.Add(new Fornecedor{Empresa=Empresa.Text.Trim(),Cnpj=Cnpj.Text.Trim(),Telefone=Telefone.Text.Trim()});await db.SaveChangesAsync();Empresa.Clear();Cnpj.Clear();Telefone.Clear();Carregar();}}